#include <csignal>
#include <iostream>

volatile std::sig_atomic_t flagged = 0;

void handle_term(int) {
    flagged = 1;
}

int main() {
    int n = 0;
    std::cin >> n;
    std::signal(SIGTERM, handle_term);
    if (n > 0) {
        std::raise(SIGTERM);
    }
    std::cout << (flagged ? "caught" : "none") << std::endl;
    return 0;
}
